#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    int furthestBuilding(vector<int>& heights, int bricks, int ladders) {
        priority_queue<int> maxHeap;
        for (int i = 0; i < heights.size() - 1; i++) {
            int diff = heights[i + 1] - heights[i];
            if (diff > 0) {
                maxHeap.push(diff);
                bricks -= diff;
                if (bricks < 0) {
                    if (ladders == 0) return i;
                    bricks += maxHeap.top();
                    maxHeap.pop();
                    ladders--;
                }
            }
        }
        return heights.size() - 1;
    }
};
